BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS vault_tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES vault_workspaces(id) ON DELETE CASCADE,name text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,name));
CREATE TABLE IF NOT EXISTS vault_object_tags(object_id uuid NOT NULL REFERENCES vault_objects(id) ON DELETE CASCADE,tag_id uuid NOT NULL REFERENCES vault_tags(id) ON DELETE CASCADE,PRIMARY KEY(object_id,tag_id));
CREATE TABLE IF NOT EXISTS vault_private_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES vault_workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL,device_id text NOT NULL,stepup_grant_id uuid,security_epoch bigint NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_vault_private_session_user ON vault_private_sessions(user_id,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS vault_secure_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES vault_workspaces(id) ON DELETE CASCADE,object_id uuid NOT NULL REFERENCES vault_objects(id) ON DELETE CASCADE,created_by uuid NOT NULL,token_hash bytea NOT NULL UNIQUE,expires_at timestamptz NOT NULL,max_downloads int,download_count int NOT NULL DEFAULT 0,require_auth boolean NOT NULL DEFAULT true,recipient_email text,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vault_share_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES vault_workspaces(id),object_id uuid NOT NULL REFERENCES vault_objects(id),sender_user_id uuid NOT NULL,recipient_user_id uuid NOT NULL,destination_workspace_id uuid,kind text NOT NULL CHECK(kind IN('LINQA_USER','VAULT_TO_VAULT')),state text NOT NULL DEFAULT 'PENDING' CHECK(state IN('PENDING','ACCEPTED','REJECTED','REVOKED','FAILED')),created_at timestamptz NOT NULL DEFAULT now(),acted_at timestamptz);
CREATE TABLE IF NOT EXISTS vault_email_shares(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),secure_link_id uuid NOT NULL REFERENCES vault_secure_links(id),recipient_email text NOT NULL,state text NOT NULL DEFAULT 'QUEUED',provider_ref text,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE TABLE IF NOT EXISTS vault_billing_customers(user_id uuid PRIMARY KEY,provider_customer_ref text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vault_billing_checkouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,workspace_id uuid NOT NULL REFERENCES vault_workspaces(id),plan_code text NOT NULL,provider text NOT NULL,provider_session_ref text UNIQUE,state text NOT NULL DEFAULT 'CREATED',idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS vault_billing_events(provider text NOT NULL,event_id text NOT NULL,payload_sha256 text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,PRIMARY KEY(provider,event_id));
CREATE TABLE IF NOT EXISTS vault_login_alert_preferences(user_id uuid PRIMARY KEY,enabled boolean NOT NULL DEFAULT true,push_enabled boolean NOT NULL DEFAULT true,email_enabled boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vault_intake_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intake_id uuid NOT NULL REFERENCES vault_intake_requests(id) ON DELETE CASCADE,source_kind text NOT NULL,source_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,plaintext_inspection_consent boolean NOT NULL DEFAULT false,client_scan_attestation jsonb,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE vault_objects ADD COLUMN IF NOT EXISTS encrypted_metadata jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE vault_objects ADD COLUMN IF NOT EXISTS source_intake_id uuid;
ALTER TABLE vault_objects ADD COLUMN IF NOT EXISTS content_encryption text NOT NULL DEFAULT 'CLIENT_E2EE';
COMMIT;
